// CLEAN: Each function does ONE thing
struct EmployeeRecord {
    string name;
    double hourlyRate;
    int hoursWorked;
};

struct Paycheck {
    string employeeName;
    double grossPay;
};

vector<string> readLinesFromFile(const string& filename) {
    ifstream file(filename);
    if (!file.is_open()) {
        throw runtime_error("Cannot open file: " + filename);
    }

    vector<string> lines;
    string line;
    while (getline(file, line)) {
        lines.push_back(line);
    }
    return lines;
}

EmployeeRecord parseEmployeeRecord(const string& csvLine) {
    stringstream ss(csvLine);
    EmployeeRecord record;

    getline(ss, record.name, ',');
    ss >> record.hourlyRate;
    ss.ignore();
    ss >> record.hoursWorked;

    return record;
}

double calculateGrossPay(double hourlyRate, int hoursWorked) {
    double regularPay = hourlyRate * min(hoursWorked, 40);
    double overtimePay = 0.0;

    if (hoursWorked > 40) {
        overtimePay = (hoursWorked - 40) * hourlyRate * 1.5;
    }

    return regularPay + overtimePay;
}

Paycheck generatePaycheck(const EmployeeRecord& employee) {
    return Paycheck{
        employee.name,
        calculateGrossPay(employee.hourlyRate, employee.hoursWorked)
    };
}

string formatPayrollReport(const vector<Paycheck>& paychecks) {
    stringstream report;
    report << "PAYROLL REPORT\n";
    report << "==============\n";

    double totalPayroll = 0.0;
    for (const auto& paycheck : paychecks) {
        report << paycheck.employeeName << ": $" << fixed << setprecision(2) 
               << paycheck.grossPay << "\n";
        totalPayroll += paycheck.grossPay;
    }

    report << "==============\n";
    report << "TOTAL: $" << totalPayroll << "\n";

    return report.str();
}

void saveReportToFile(const string& report, const string& filename) {
    ofstream file(filename);
    if (!file.is_open()) {
        throw runtime_error("Cannot write to: " + filename);
    }
    file << report;
}

void sendPayStubNotification(const Paycheck& paycheck) {
    cout << "[Email] Pay stub for " << paycheck.employeeName 
         << ": $" << paycheck.grossPay << "\n";
}

// The high-level function reads like a story
void processPayrollClean() {
    auto lines = readLinesFromFile("employees.txt");

    vector<EmployeeRecord> employees;
    for (const auto& line : lines) {
        employees.push_back(parseEmployeeRecord(line));
    }

    vector<Paycheck> paychecks;
    for (const auto& employee : employees) {
        paychecks.push_back(generatePaycheck(employee));
    }

    string report = formatPayrollReport(paychecks);
    saveReportToFile(report, "payroll_report.txt");

    for (const auto& paycheck : paychecks) {
        sendPayStubNotification(paycheck);
    }
}

