/**
 * @brief A thread-safe cache for storing computed values.
 * 
 * @tparam Key The type used to identify cached entries. Must be hashable.
 * @tparam Value The type of the cached values.
 * 
 * @thread_safety All public methods are safe to call concurrently.
 * 
 * @code
 * ThreadSafeCache<string, vector<double>> cache;
 * cache.put("matrix_a", computeMatrix());
 * auto result = cache.get("matrix_a");  // Returns cached value
 * @endcode
 */
template<typename Key, typename Value>
class ThreadSafeCache {
public:
    /**
     * @brief Stores a value in the cache.
     * 
     * If the key already exists, the old value is overwritten.
     * 
     * @param key The identifier for the cached entry.
     * @param value The value to store.
     * @throws std::bad_alloc If memory allocation fails.
     */
    void put(const Key& key, const Value& value);

    /**
     * @brief Retrieves a value from the cache.
     * 
     * @param key The identifier for the cached entry.
     * @return std::optional<Value> The cached value if found, std::nullopt otherwise.
     * 
     * @note This method does not throw. Use has() to check existence
     *       if you need to distinguish between a missing key and a
     *       nullopt-stored value.
     */
    optional<Value> get(const Key& key) const;

    /**
     * @brief Checks if a key exists in the cache.
     * @param key The identifier to check.
     * @return true if the key exists, false otherwise.
     */
    bool has(const Key& key) const;

    /**
     * @brief Removes all entries from the cache.
     * 
     * @post size() == 0
     */
    void clear();

    /**
     * @brief Returns the number of entries in the cache.
     */
    size_t size() const;

private:
    mutable mutex mutex_;
    unordered_map<Key, Value> data_;
};

