// BAD: Exposed internals, no invariant protection
class DateRangeBad {
public:
    chrono::system_clock::time_point start;
    chrono::system_clock::time_point end;

    // Callers can set end before start — invariant violated!
};

// CLEAN: Encapsulated, invariants protected
class DateRange {
public:
    DateRange(chrono::system_clock::time_point start,
              chrono::system_clock::time_point end)
        : start_(start), end_(end) {
        if (end_ <= start_) {
            throw invalid_argument("End must be after start");
        }
    }

    chrono::system_clock::time_point start() const { return start_; }
    chrono::system_clock::time_point end() const { return end_; }

    void setStart(chrono::system_clock::time_point newStart) {
        if (newStart >= end_) {
            throw invalid_argument("Start must be before end");
        }
        start_ = newStart;
    }

    void setEnd(chrono::system_clock::time_point newEnd) {
        if (newEnd <= start_) {
            throw invalid_argument("End must be after start");
        }
        end_ = newEnd;
    }

    chrono::seconds duration() const {
        return chrono::duration_cast<chrono::seconds>(end_ - start_);
    }

    bool contains(chrono::system_clock::time_point point) const {
        return point >= start_ && point <= end_;
    }

    bool overlaps(const DateRange& other) const {
        return start_ < other.end_ && end_ > other.start_;
    }

private:
    chrono::system_clock::time_point start_;
    chrono::system_clock::time_point end_;
};

// BAD: Exposed collection — callers can break invariants
class ClassroomBad {
public:
    vector<Student> students;  // Public! Callers can add duplicates
    int maxCapacity = 30;
};

// CLEAN: Controlled access to internal collection
class Classroom {
public:
    explicit Classroom(int maxCapacity) : maxCapacity_(maxCapacity) {}

    bool enroll(const Student& student) {
        if (students_.size() >= maxCapacity_) {
            return false;  // Full
        }
        if (isEnrolled(student.id())) {
            return false;  // Already enrolled — no duplicates
        }
        students_.push_back(student);
        return true;
    }

    bool withdraw(const string& studentId) {
        auto it = find_if(students_.begin(), students_.end(),
                          [&studentId](const auto& s) { return s.id() == studentId; });
        if (it == students_.end()) return false;
        students_.erase(it);
        return true;
    }

    bool isEnrolled(const string& studentId) const {
        return any_of(students_.begin(), students_.end(),
                      [&studentId](const auto& s) { return s.id() == studentId; });
    }

    size_t enrollmentCount() const { return students_.size(); }
    bool isFull() const { return students_.size() >= maxCapacity_; }

    // Read-only access — returns const reference
    const vector<Student>& enrolledStudents() const { return students_; }

private:
    int maxCapacity_;
    vector<Student> students_;
};

// Uniform Access Principle: computed vs stored looks the same
class Circle {
    double radius_;
    mutable optional<double> cachedArea_;  // Lazy computation

public:
    explicit Circle(double radius) : radius_(radius) {}

    double radius() const { return radius_; }

    // Client cannot tell this is computed (not stored)
    double area() const {
        if (!cachedArea_) {
            cachedArea_ = M_PI * radius_ * radius_;
        }
        return *cachedArea_;
    }

    // Also computed
    double circumference() const {
        return 2 * M_PI * radius_;
    }

    // Also computed
    double diameter() const {
        return 2 * radius_;
    }
};

// Protected Variation: shipping strategies behind common interface
class ShippingStrategy {
public:
    virtual ~ShippingStrategy() = default;
    virtual double calculateCost(double weight, const Address& destination) const = 0;
    virtual chrono::days estimatedDelivery() const = 0;
    virtual string getName() const = 0;
};

class StandardShipping : public ShippingStrategy {
public:
    double calculateCost(double weight, const Address&) const override {
        return 5.99 + weight * 0.50;
    }
    chrono::days estimatedDelivery() const override { return chrono::days(5); }
    string getName() const override { return "Standard"; }
};

class ExpressShipping : public ShippingStrategy {
public:
    double calculateCost(double weight, const Address&) const override {
        return 15.99 + weight * 1.20;
    }
    chrono::days estimatedDelivery() const override { return chrono::days(2); }
    string getName() const override { return "Express"; }
};

class InternationalShipping : public ShippingStrategy {
public:
    double calculateCost(double weight, const Address& destination) const override {
        double base = destination.country == "USA" ? 25.0 : 35.0;
        return base + weight * 2.50;
    }
    chrono::days estimatedDelivery() const override { return chrono::days(14); }
    string getName() const override { return "International"; }
};

class Shipment {
    unique_ptr<ShippingStrategy> strategy_;
    double weight_;
    Address destination_;

public:
    Shipment(unique_ptr<ShippingStrategy> strategy, double weight, Address dest)
        : strategy_(move(strategy)), weight_(weight), destination_(move(dest)) {}

    double shippingCost() const {
        return strategy_->calculateCost(weight_, destination_);
    }

    chrono::days deliveryTime() const {
        return strategy_->estimatedDelivery();
    }

    string methodName() const {
        return strategy_->getName();
    }
};

